using System;
using System.IO;
using UnityEngine;
using UnityEditor;
namespace LWS.TruckDockDiving.Editor {
public static class DockAudioAuthoring {
 public static AudioClip[] Create(){var a=new AudioClip[8];a[0]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Heat - Complete Modern UI/Audio/Click.wav");a[2]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/WeatherMaker/Prefab/Sound/Water/WeatherMakerWaterSound_Splash.ogg");a[4]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckBowling/Audio/Delivery.wav");a[7]=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckBowling/Audio/Winner.wav");string[] names={"Ordinary applause","Playful crowd boo","Strong applause","Exceptional cheer"};int[] slots={1,3,5,6};for(int k=0;k<names.Length;k++){string path="Assets/TruckDockDiving/Audio/"+names[k]+".wav";if(!File.Exists(path))Write(path,k);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);a[slots[k]]=AssetDatabase.LoadAssetAtPath<AudioClip>(path);}return a;}
 static void Write(string path,int kind){const int rate=22050;float duration=kind==3?2.1f:kind==2?1.5f:1.0f;int n=(int)(rate*duration);var rng=new System.Random(971+kind);using(var w=new BinaryWriter(File.Create(path))){w.Write(System.Text.Encoding.ASCII.GetBytes("RIFF"));w.Write(36+n*2);w.Write(System.Text.Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((short)1);w.Write((short)1);w.Write(rate);w.Write(rate*2);w.Write((short)2);w.Write((short)16);w.Write(System.Text.Encoding.ASCII.GetBytes("data"));w.Write(n*2);float low=0;for(int i=0;i<n;i++){float t=i/(float)rate;float noise=(float)rng.NextDouble()*2-1;low=Mathf.Lerp(low,noise,.12f);float edge=Mathf.Min(1,t*8)*Mathf.Min(1,(duration-t)*4);float sum=0;if(kind==1){for(int voice=0;voice<7;voice++){float hz=105+voice*9+Mathf.Sin(t*2+voice)*5;sum+=Mathf.Sin(2*Mathf.PI*hz*t+voice)*.065f+Mathf.Sin(2*Mathf.PI*hz*2*t+voice)*.025f;}sum+=low*.18f;}else {for(int clapper=0;clapper<11;clapper++){float period=.15f+clapper*.013f;float age=Mathf.Repeat(t+clapper*.037f,period);sum+=noise*Mathf.Exp(-age*110)*.09f;}if(kind>=2)sum+=low*.8f+Mathf.Sin(2*Mathf.PI*(440+Mathf.Sin(t*8)*65)*t)*.035f;}w.Write((short)(Mathf.Clamp(sum*edge,-.9f,.9f)*short.MaxValue));}}}
}
}
